// The other package. Same template name, a third type argument, and a `get`
// that negates — so `@Holder$i32.get`, `@pkg_a.Holder$i64.get` and
// `@pkg_b.Holder$f64.get` all have to be separate symbols with separate facts.
class Holder<T> {
  value: T;

  constructor(v: T) {
    this.value = v;
  }

  get(): T {
    return -this.value;
  }
}

export const fromB = (): i32 => toI32(new Holder<f64>(3.0).get());
